double h = (b - a) / N;
double sum = 0.5 * (f(a) + f(b)); // Initialize sum with the first and last terms
for (int i = 1; i < N; i++) {
    double x = a + i * h; // Calculate the x value for the current subinterval
    sum += f(x); // Add the function value at x to the sum
}
return h * sum; // Return the approximate integral value

